+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.*;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    private TextField name() { return $(TextField.class).withLabel("Name").single(); }
+    private TextField phone() { return $(TextField.class).withLabel("Phone").single(); }
+    private EmailField email() { return $(EmailField.class).single(); }
+    private TextArea message() { return $(TextArea.class).single(); }
+    private Button send() { return $(Button.class).withText("Send").single(); }
+    private void click(String text) { test($(Button.class).withText(text).single()).click(); }
+    private int rows() { return $(Grid.class).single().getDataProvider().size(new Query<>()); }
+
+    @Test void validationAndSuccessfulSend() {
+        navigate(ContactView.class);
+        int before = rows();
+        assertTrue(send().isEnabled());
+        click("Send");
+        assertEquals("Name is required", name().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertTrue(email().isInvalid());
+        assertTrue(message().isInvalid());
+        assertFalse($(Notification.class).exists());
+        assertEquals(before, rows());
+        test(name()).setValue("Ada");
+        test(email()).setValue("bad-address");
+        test(message()).setValue("x".repeat(501));
+        click("Send");
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("x".repeat(501), message().getValue());
+        test(email()).setValue("");
+        test(phone()).setValue("12345");
+        test(message()).setValue("Hello");
+        fireShortcut(Key.ENTER);
+        assertEquals(before + 1, rows());
+        assertTrue($(Notification.class).exists());
+        assertTrue(name().isEmpty() && phone().isEmpty() && email().isEmpty() && message().isEmpty());
+        assertFalse(send().isEnabled());
+        test(name()).setValue("Grace");
+        assertTrue(send().isEnabled());
+        test(email()).setValue("grace@example.com");
+        test(message()).setValue("Second message");
+        click("Send");
+        assertEquals(before + 2, rows());
+        var first = (MessageStore.SentMessage) $(Grid.class).single().getDataProvider().fetch(new Query<>()).findFirst().orElseThrow();
+        assertEquals("Grace", first.name());
+        test($(RouterLink.class).single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        assertFalse($(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertEquals(before + 2, rows());
+    }
+
+    @Test void navigationGuardPreservesDraftAndAllowsDiscard() {
+        navigate(ContactView.class);
+        test(message()).setValue("Draft");
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        click("Keep editing");
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("Draft", message().getValue());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue($(Dialog.class).single().isOpened());
+        click("Discard");
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test void eachFieldProtectsDraftIncludingWhitespace() {
+        for (String label : new String[]{"Name", "Email", "Phone", "Message"}) {
+            navigate(ContactView.class);
+            switch (label) {
+                case "Name" -> test(name()).setValue(" ");
+                case "Email" -> test(email()).setValue("a@example.com");
+                case "Phone" -> test(phone()).setValue("1");
+                case "Message" -> test(message()).setValue("Draft");
+            }
+            UI.getCurrent().navigate(AboutView.class);
+            assertTrue($(Dialog.class).single().isOpened(), label);
+            click("Discard");
+            assertEquals("About", $(H1.class).single().getText());
+        }
+    }
+}
